(7156885, 1097583, 114225, '<td valign="top">The light here is striking.</td>', 'The light here is striking.', '2014-01-13 13:14:58.000000', NULL, 1),
(7156886, 1097021, 114225, '<td valign="top">I''m not taking points off for the border, but I find it so very distracting for this photo.</td>', 'I''m not taking points off for the border, but I find it so very distracting for this photo.', '2014-01-13 13:15:35.000000', NULL, 1),
(7156887, 1097621, 114225, '<td valign="top">Oh, you bought the automatic lens cap. Do you like it?</td>', 'Oh, you bought the automatic lens cap. Do you like it?', '2014-01-13 13:16:08.000000', NULL, 1),
(7156888, 1097035, 114225, '<td valign="top">Very well done.</td>', 'Very well done.', '2014-01-13 13:16:29.000000', NULL, 1),
(7156908, 1097464, 173844, '<td valign="top">Deliciously blue, balanced both in form and coloration. Altogether pleasing.</td>', 'Deliciously blue, balanced both in form and coloration. Altogether pleasing.', '2014-01-13 14:21:47.000000', NULL, 1),
(7156913, 1097599, 173844, '<td valign="top">Beautiful landscape, curiously modest amid the majesty.  The wonderful clouds and sky are echoed below by snow and water.</td>', 'Beautiful landscape, curiously modest amid the majesty.  The wonderful clouds and sky are echoed below by snow and water.', '2014-01-13 14:25:43.000000', NULL, 1),
(7156918, 1097559, 173844, '<td valign="top">Nicely jumbled buildings fronted by a shattered sea, featuring a luminous boat and embraced by a glorious, understated sunset.  And it''s all beautifully composed and serene.  I''ve lingered over this one.</td>', 'Nicely jumbled buildings fronted by a shattered sea, featuring a luminous boat and embraced by a glorious, understated sunset.  And it''s all beautifully composed and serene.  I''ve lingered over this one.', '2014-01-13 14:32:49.000000', NULL, 1),
(7156920, 1097200, 173844, '<td valign="top">There''s a purity to this black and white that manages to just hint at the larger whole.  The light masterfully brings out the shapes and textures.</td>', 'There''s a purity to this black and white that manages to just hint at the larger whole.  The light masterfully brings out the shapes and textures.', '2014-01-13 14:36:30.000000', NULL, 1),
(7156924, 1097516, 173844, '<td valign="top">Amazing sky and reflection.  It''s like being inside a magical clam.</td>', 'Amazing sky and reflection.  It''s like being inside a magical clam.', '2014-01-13 14:42:45.000000', NULL, 1),
(7156927, 1097329, 173844, '<td valign="top">You can almost smell the ocean at this low tide, mingling the senses with the awesome sunrise.  Very fine image.</td>', 'You can almost smell the ocean at this low tide, mingling the senses with the awesome sunrise.  Very fine image.', '2014-01-13 14:45:54.000000', NULL, 1),
(7156930, 1097596, 173844, '<td valign="top">Artfully high exposure brings the brightness of morning into this winning portrait.  Even her pupils are wide open.  Fun image, too.</td>', 'Artfully high exposure brings the brightness of morning into this winning portrait.  Even her pupils are wide open.  Fun image, too.', '2014-01-13 14:53:34.000000', NULL, 1),
(7156934, 1097581, 173844, '<td valign="top">Delightful, offbeat image; beguiling in its delicate strangeness.</td>', 'Delightful, offbeat image; beguiling in its delicate strangeness.', '2014-01-13 14:58:12.000000', NULL, 1),
(7156951, 1097265, 173844, '<td valign="top">Totally believable, aptly toned and with a strong sense of suspense.  Powerful image.  The border, however, in my opinion, limits the grandeur.</td>', 'Totally believable, aptly toned and with a strong sense of suspense.  Powerful image.  The border, however, in my opinion, limits the grandeur.', '2014-01-13 15:07:48.000000', NULL, 1),
(7156952, 1097623, 173844, '<td valign="top">Timeless feel to this serene landscape suffused with dawn.</td>', 'Timeless feel to this serene landscape suffused with dawn.', '2014-01-13 15:12:10.000000', NULL, 1),
(7156953, 1097614, 173844, '<td valign="top">Marvelous study in ivory of this intriguing bloom.  Very satisfying to look at.  Nicely framed.</td>', 'Marvelous study in ivory of this intriguing bloom.  Very satisfying to look at.  Nicely framed.', '2014-01-13 15:16:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7156956, 1097533, 173844, '<td valign="top">Very fine street scene, perfectly timed to the nun''s entry.  Appealing glow to it.  Bold decision to centrally feature the light expanse of stone walkway, enhancing overall contrast.</td>', 'Very fine street scene, perfectly timed to the nun''s entry.  Appealing glow to it.  Bold decision to centrally feature the light expanse of stone walkway, enhancing overall contrast.', '2014-01-13 15:34:07.000000', NULL, 1),
(7156958, 1097593, 173844, '<td valign="top">Excellent, suitably somber photo.  Quietly moving.  The central area looks like a Chinese character.</td>', 'Excellent, suitably somber photo.  Quietly moving.  The central area looks like a Chinese character.', '2014-01-13 15:37:02.000000', NULL, 1),
(7156965, 1097644, 173844, '<td valign="top">Adorable, well-focused cat.  Nicely set off by the red cloth.  Beautiful eyes.</td>', 'Adorable, well-focused cat.  Nicely set off by the red cloth.  Beautiful eyes.', '2014-01-13 16:06:55.000000', NULL, 1),
(7156966, 1097519, 173844, '<td valign="top">Wonderfully golden wedding picture.</td>', 'Wonderfully golden wedding picture.', '2014-01-13 16:07:48.000000', NULL, 1),
