(7156992, 1097598, 173350, '<td valign="top">Very creative and well executed.</td>', 'Very creative and well executed.', '2014-01-13 17:47:46.000000', NULL, 1),
(7156994, 1097245, 173350, '<td valign="top">Beautiful framing and tonality, but I find the texture rather distracting.</td>', 'Beautiful framing and tonality, but I find the texture rather distracting.', '2014-01-13 17:49:23.000000', NULL, 1),
(7156998, 1097599, 173350, '<td valign="top">Nice contrast. Lots of interesting textures. Very stare-worthy!</td>', 'Nice contrast. Lots of interesting textures. Very stare-worthy!', '2014-01-13 17:55:19.000000', NULL, 1),
(7157000, 1097601, 173350, '<td valign="top">Lots of feeling captured here.  Well done!</td>', 'Lots of feeling captured here.  Well done!', '2014-01-13 17:56:22.000000', NULL, 1),
(7157005, 1097647, 173350, '<td valign="top">The background blurring feels a little "photoshopped" but that''s being nitpicky. The expressions on those dogs are incredible and I really like this shot overally.</td>', 'The background blurring feels a little "photoshopped" but that''s being nitpicky. The expressions on those dogs are incredible and I really like this shot overally.', '2014-01-13 18:04:06.000000', NULL, 1),
(7157007, 1097586, 173350, '<td valign="top">Perfectly lit, simple and elegent.</td>', 'Perfectly lit, simple and elegent.', '2014-01-13 18:04:30.000000', NULL, 1),
(7157008, 1097591, 173350, '<td valign="top">The reddish-greenish tonality is a little distracting as is the fuzzyness but I''m still amazed by this shot. To appease my ego, please say this took dozens of attemps over several days. LOL</td>', 'The reddish-greenish tonality is a little distracting as is the fuzzyness but I''m still amazed by this shot. To appease my ego, please say this took dozens of attemps over several days. LOL', '2014-01-13 18:07:18.000000', NULL, 1),
(7157009, 1097516, 173350, '<td valign="top">Lots of interesting patterns. A photo you can look at for quite a long time.</td>', 'Lots of interesting patterns. A photo you can look at for quite a long time.', '2014-01-13 18:08:22.000000', NULL, 1),
(7157010, 1097436, 173350, '<td valign="top">Perfectly lit and composed. Sharp as a razor. I can almost feel that prickly beard.</td>', 'Perfectly lit and composed. Sharp as a razor. I can almost feel that prickly beard.', '2014-01-13 18:09:45.000000', NULL, 1),
(7157016, 1097600, 173350, '<td valign="top">Interesting and beautiful.  The texture is a little distracting to me though.</td>', 'Interesting and beautiful.  The texture is a little distracting to me though.', '2014-01-13 18:13:15.000000', NULL, 1),
(7157017, 1097519, 173350, '<td valign="top">This is a beautiful shot. I think I would rate it higher if the couple were a little crisper. As is, it feels a little like trying to straddle the line between an artsy print and a wedding album shot without committing to either.</td>', 'This is a beautiful shot. I think I would rate it higher if the couple were a little crisper. As is, it feels a little like trying to straddle the line between an artsy print and a wedding album shot without committing to either.', '2014-01-13 18:16:19.000000', NULL, 1),
(7157018, 1097583, 173350, '<td valign="top">Nicely composed! It really draws me in to the frame.</td>', 'Nicely composed! It really draws me in to the frame.', '2014-01-13 18:17:08.000000', NULL, 1),
(7157020, 1097460, 173350, '<td valign="top">I can feel the photographers (many?) attempts at getting the timing just right.  Was it as fun to do as it looks?</td>', 'I can feel the photographers (many?) attempts at getting the timing just right.  Was it as fun to do as it looks?', '2014-01-13 18:19:01.000000', NULL, 1),
